// Serves the app's Amp portal on one origin. Generated by Amplify (https://github.com/springloadedco/amplify).
//
// A page on one portal cannot reach another portal's hostname, so everything the browser talks
// to shares the app's origin:
//   /__vite/*            → the Vite dev server, including its HMR websocket
//   other websockets     → Reverb (its /app/{key} paths are unchanged, so Echo needs no options)
//   everything else      → `php artisan serve`

import http from 'node:http'
import net from 'node:net'

// Ports come from .amp/orb.env.
const appPort = Number(process.env.AMPLIFY_APP_PORT)
const vitePort = Number(process.env.AMPLIFY_VITE_PORT)
const reverbPort = Number(process.env.REVERB_PORT)

const isVite = (url) => url === '/__vite' || url.startsWith('/__vite/')

// Services start in parallel, so a request can arrive before its upstream listens. Retry
// refused connections for a while instead of failing the first page load. The body is buffered
// so it can be resent; this is a development proxy.
const RETRY_MS = 250
const RETRY_FOR_MS = 30_000

const server = http.createServer((request, response) => {
	const port = isVite(request.url) ? vitePort : appPort
	const chunks = []
	request.on('data', (chunk) => chunks.push(chunk))
	request.on('end', () => forward(Buffer.concat(chunks), Date.now()))

	function forward(body, startedAt) {
		const upstream = http.request(
			{ host: '127.0.0.1', port, path: request.url, method: request.method, headers: request.headers },
			(upstreamResponse) => {
				response.writeHead(upstreamResponse.statusCode, upstreamResponse.headers)
				upstreamResponse.pipe(response)
			},
		)
		upstream.on('error', (error) => {
			if (error.code === 'ECONNREFUSED' && Date.now() - startedAt < RETRY_FOR_MS) {
				return setTimeout(() => forward(body, startedAt), RETRY_MS)
			}
			if (!response.headersSent) response.writeHead(502, { 'content-type': 'text/plain' })
			response.end(`Nothing is listening on port ${port}. Check \`amp orb service logs\` for the app and vite services.\n`)
		})
		upstream.end(body)
	}
})

server.on('upgrade', (request, socket, head) => {
	const port = isVite(request.url) ? vitePort : reverbPort
	if (!port) return socket.destroy()
	const upstream = net.connect(port, '127.0.0.1', () => {
		const headers = []
		for (let i = 0; i < request.rawHeaders.length; i += 2) {
			headers.push(`${request.rawHeaders[i]}: ${request.rawHeaders[i + 1]}`)
		}
		upstream.write(`${request.method} ${request.url} HTTP/1.1\r\n${headers.join('\r\n')}\r\n\r\n`)
		upstream.write(head)
		upstream.pipe(socket).pipe(upstream)
	})
	upstream.on('error', () => socket.destroy())
	socket.on('error', () => upstream.destroy())
})

server.listen(Number(process.env.PORT), '0.0.0.0')
